class _UniffiConverterTypeProxyClient:

    @staticmethod
    def lift(value: int):
        return ProxyClient._make_instance_(value)

    @staticmethod
    def check_lower(value: ProxyClient):
        if not isinstance(value, ProxyClient):
            raise TypeError("Expected ProxyClient instance, {} found".format(type(value).__name__))

    @staticmethod
    def lower(value: ProxyClientProtocol):
        if not isinstance(value, ProxyClient):
            raise TypeError("Expected ProxyClient instance, {} found".format(type(value).__name__))
        return value._uniffi_clone_pointer()

    @classmethod
    def read(cls, buf: _UniffiRustBuffer):
        ptr = buf.read_u64()
        if ptr == 0:
            raise InternalError("Raw pointer value was null")
        return cls.lift(ptr)

    @classmethod
    def write(cls, value: ProxyClientProtocol, buf: _UniffiRustBuffer):
        buf.write_u64(cls.lower(value))


class ProxyConfig:
    """
    Options for [`ProxyClient::new`]. In production a host passes only
    `publisherId`; the gateway address and CA are development overrides.
    """

    publisher_id: "str"
    gateway_addresses: "typing.List[str]"
    ca_cert_path: "typing.Optional[str]"
    ca_cert_pem: "typing.Optional[bytes]"
    start_timeout_ms: "typing.Optional[int]"
    connect_timeout_ms: "typing.Optional[int]"
    device_id: "typing.Optional[str]"
    """
    Stable id for this machine, if the host keeps one. The SDK never mints or
    stores it — only the host knows where an id belongs on its platform.
    """

    device_name: "typing.Optional[str]"
    """
    A human name for this machine, conventionally its hostname.
    """

    sdk: "typing.Optional[str]"
    """
    Which binding is calling: "python", "ruby", "go", "swift", "kotlin".
    Unlike the node binding, this crate cannot detect it — uniffi generates
    all five from this one crate — so a host that wants its language
    attributed correctly sets it here. Defaults to the SDK's own default.
    """

    app: "typing.Optional[str]"
    """
    The host application, e.g. "my-app/2.1.0".
    """

    network: "typing.Optional[str]"
    """
    The transport the host is on at start: "cellular", "wifi", "ethernet"
    or "other". Report later changes with `set_network`.
    """

    def __init__(self, *, publisher_id: "str", gateway_addresses: "typing.List[str]", ca_cert_path: "typing.Optional[str]" = _DEFAULT, ca_cert_pem: "typing.Optional[bytes]" = _DEFAULT, start_timeout_ms: "typing.Optional[int]" = _DEFAULT, connect_timeout_ms: "typing.Optional[int]" = _DEFAULT, device_id: "typing.Optional[str]" = _DEFAULT, device_name: "typing.Optional[str]" = _DEFAULT, sdk: "typing.Optional[str]" = _DEFAULT, app: "typing.Optional[str]" = _DEFAULT, network: "typing.Optional[str]" = _DEFAULT):
        self.publisher_id = publisher_id
        self.gateway_addresses = gateway_addresses
        if ca_cert_path is _DEFAULT:
            self.ca_cert_path = None
        else:
            self.ca_cert_path = ca_cert_path
        if ca_cert_pem is _DEFAULT:
            self.ca_cert_pem = None
        else:
            self.ca_cert_pem = ca_cert_pem
        if start_timeout_ms is _DEFAULT:
            self.start_timeout_ms = None
        else:
            self.start_timeout_ms = start_timeout_ms
        if connect_timeout_ms is _DEFAULT:
            self.connect_timeout_ms = None
        else:
            self.connect_timeout_ms = connect_timeout_ms
        if device_id is _DEFAULT:
            self.device_id = None
        else:
            self.device_id = device_id
        if device_name is _DEFAULT:
            self.device_name = None
        else:
            self.device_name = device_name
        if sdk is _DEFAULT:
            self.sdk = None
        else:
            self.sdk = sdk
        if app is _DEFAULT:
            self.app = None
        else:
            self.app = app
        if network is _DEFAULT:
            self.network = None
        else:
            self.network = network

    def __str__(self):
        return "ProxyConfig(publisher_id={}, gateway_addresses={}, ca_cert_path={}, ca_cert_pem={}, start_timeout_ms={}, connect_timeout_ms={}, device_id={}, device_name={}, sdk={}, app={}, network={})".format(self.publisher_id, self.gateway_addresses, self.ca_cert_path, self.ca_cert_pem, self.start_timeout_ms, self.connect_timeout_ms, self.device_id, self.device_name, self.sdk, self.app, self.network)

    def __eq__(self, other):
        if self.publisher_id != other.publisher_id:
            return False
        if self.gateway_addresses != other.gateway_addresses:
            return False
        if self.ca_cert_path != other.ca_cert_path:
            return False
        if self.ca_cert_pem != other.ca_cert_pem:
            return False
        if self.start_timeout_ms != other.start_timeout_ms:
            return False
        if self.connect_timeout_ms != other.connect_timeout_ms:
            return False
        if self.device_id != other.device_id:
            return False
        if self.device_name != other.device_name:
            return False
        if self.sdk != other.sdk:
            return False
        if self.app != other.app:
            return False
        if self.network != other.network:
            return False
        return True

