class ClientState(enum.Enum):
    """
    What the client is currently doing.
    """

    IDLE = 0
    
    CONNECTING = 1
    
    CONNECTED = 2
    
    STOPPED = 3
    


class _UniffiConverterTypeClientState(_UniffiConverterRustBuffer):
    @staticmethod
    def read(buf):
        variant = buf.read_i32()
        if variant == 1:
            return ClientState.IDLE
        if variant == 2:
            return ClientState.CONNECTING
        if variant == 3:
            return ClientState.CONNECTED
        if variant == 4:
            return ClientState.STOPPED
        raise InternalError("Raw enum value doesn't match any cases")

    @staticmethod
    def check_lower(value):
        if value == ClientState.IDLE:
            return
        if value == ClientState.CONNECTING:
            return
        if value == ClientState.CONNECTED:
            return
        if value == ClientState.STOPPED:
            return
        raise ValueError(value)

    @staticmethod
    def write(value, buf):
        if value == ClientState.IDLE:
            buf.write_i32(1)
        if value == ClientState.CONNECTING:
            buf.write_i32(2)
        if value == ClientState.CONNECTED:
            buf.write_i32(3)
        if value == ClientState.STOPPED:
            buf.write_i32(4)




# ProxyError
# We want to define each variant as a nested class that's also a subclass,
# which is tricky in Python.  To accomplish this we're going to create each
# class separately, then manually add the child classes to the base class's
# __dict__.  All of this happens in dummy class to avoid polluting the module
# namespace.
class ProxyError(Exception):
    """
    The single error every fallible SDK call returns.

    The field is `reason`, not `message`, and that is not a style choice. uniffi
    generates the Kotlin variant as a subclass of `kotlin.Exception` with an
    `override val message`, so a field literally named `message` collides with
    `Throwable.message` and the generated Kotlin does not compile. Upstream's
    answer is to not name an error field `message`. Nothing else reads the name,
    and Kotlin callers still get the text through `e.message` as usual.
    """

    pass

_UniffiTempProxyError = ProxyError

class ProxyError:  # type: ignore
    """
    The single error every fallible SDK call returns.

    The field is `reason`, not `message`, and that is not a style choice. uniffi
    generates the Kotlin variant as a subclass of `kotlin.Exception` with an
    `override val message`, so a field literally named `message` collides with
    `Throwable.message` and the generated Kotlin does not compile. Upstream's
    answer is to not name an error field `message`. Nothing else reads the name,
    and Kotlin callers still get the text through `e.message` as usual.
    """

    class Failed(_UniffiTempProxyError):
        def __init__(self, reason):
            super().__init__(", ".join([
                "reason={!r}".format(reason),
            ]))
            self.reason = reason

        def __repr__(self):
            return "ProxyError.Failed({})".format(str(self))
    _UniffiTempProxyError.Failed = Failed # type: ignore

ProxyError = _UniffiTempProxyError # type: ignore
del _UniffiTempProxyError


class _UniffiConverterTypeProxyError(_UniffiConverterRustBuffer):
    @staticmethod
    def read(buf):
        variant = buf.read_i32()
        if variant == 1:
            return ProxyError.Failed(
                _UniffiConverterString.read(buf),
            )
        raise InternalError("Raw enum value doesn't match any cases")

    @staticmethod
    def check_lower(value):
        if isinstance(value, ProxyError.Failed):
            _UniffiConverterString.check_lower(value.reason)
            return

    @staticmethod
    def write(value, buf):
        if isinstance(value, ProxyError.Failed):
            buf.write_i32(1)
            _UniffiConverterString.write(value.reason, buf)



class _UniffiConverterOptionalUInt32(_UniffiConverterRustBuffer):
    @classmethod
    def check_lower(cls, value):
        if value is not None:
            _UniffiConverterUInt32.check_lower(value)

    @classmethod
    def write(cls, value, buf):
        if value is None:
            buf.write_u8(0)
            return

        buf.write_u8(1)
        _UniffiConverterUInt32.write(value, buf)

    @classmethod
    def read(cls, buf):
        flag = buf.read_u8()
        if flag == 0:
            return None
        elif flag == 1:
            return _UniffiConverterUInt32.read(buf)
        else:
            raise InternalError("Unexpected flag byte for optional type")



